import boto3

from speech_client import get_transcribe_client


def poll_transcription(job_id, config=None):
    config = config or {}
    client = get_transcribe_client(config)
    response = client.get_transcription_job(TranscriptionJobName=job_id)
    job = response["TranscriptionJob"]
    return {
        "job_id": job["TranscriptionJobName"],
        "status": job["TranscriptionJobStatus"],
        "transcript": job.get("Transcript", {})
    }

import boto3


def get_transcribe_client(config):
    return boto3.client("transcribe", region_name=config.get("region"))


def get_translate_client(config):
    return boto3.client("translate", region_name=config.get("region"))


def get_comprehend_client(config):
    return boto3.client("comprehend", region_name=config.get("region"))


def get_textract_client(config):
    return boto3.client("textract", region_name=config.get("region"))

from typing import Dict, Any


def normalize_transcription_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "language_code": payload.get("language_code", "en-US"),
        "audio_uri": payload["audio_uri"],
    }


def normalize_translation_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "text": payload["text"],
        "source_language_code": payload.get("source_language_code", "en"),
        "target_language_code": payload["target_language_code"],
    }

import boto3

from speech_client import get_comprehend_client


def moderate_transcript(transcript, config=None):
    config = config or {}
    client = get_comprehend_client(config)
    response = client.detect_sentiment(
        Text=transcript,
        LanguageCode="en"
    )
    sentiment = response["Sentiment"]
    if sentiment == "NEGATIVE":
        return "Moderation failed: Negative sentiment detected."
    return "Moderation passed."
